// Loads the Blender-built course models (src/assets/models, generated by `npm run assets`)
// and turns them into reusable, purely visual pieces. Collision stays in physics.ts.
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import cupUrl from './assets/models/cup.glb?url';
import decorUrl from './assets/models/decor.glb?url';
import gardenUrl from './assets/models/garden.glb?url';
import lanternUrl from './assets/models/lantern.glb?url';
import rocksUrl from './assets/models/rocks.glb?url';
import wallsUrl from './assets/models/walls.glb?url';
import windmillUrl from './assets/models/windmill.glb?url';
import { modelMaterials } from './art';

export interface Models {
  windmill: THREE.Object3D;
  /** Named single pieces: wall kit, Cup, Lantern, Rocks1..3, Barrel, Planter, and the garden set (TimberSection, TimberPost, Hedge, Tree, Flower, Paver1..3, LampPost) */
  pieces: Map<string, THREE.Object3D>;
}

/** Wall kit dimensions (must match assets-src/blender/props.py). */
export const KIT = { section: 48, bodyH: 34, capH: 6 };

let loaded: Models | null = null;
let loading: Promise<Models> | null = null;

export function getModels() { return loaded; }

export function loadModels(onProgress?: (p: number) => void): Promise<Models> {
  if (loading) return loading;
  const loader = new GLTFLoader();
  const lib = modelMaterials();
  const urls = [windmillUrl, wallsUrl, cupUrl, lanternUrl, rocksUrl, decorUrl, gardenUrl];
  let done = 0;
  loading = Promise.all(urls.map((u) => loader.loadAsync(u).then((g) => { onProgress?.(++done / urls.length); return g; })))
    .then(([windmill, walls, cup, lantern, rocks, decor, garden]) => {
      const pieces = new Map<string, THREE.Object3D>();
      for (const gltf of [windmill, walls, cup, lantern, rocks, decor, garden]) {
        gltf.scene.traverse((o) => {
          if (o instanceof THREE.Mesh) {
            const name = (o.material as THREE.Material).name;
            o.material = lib[name] ?? o.material;
            o.castShadow = name !== 'Hole' && name !== 'Glass';
            o.receiveShadow = true;
          }
        });
        if (gltf !== windmill) for (const child of gltf.scene.children) pieces.set(child.name, child);
      }
      loaded = { windmill: windmill.scene, pieces };
      return loaded;
    });
  return loading;
}

/** A fresh copy of a piece (geometry and materials are shared, so this is cheap). */
export function clonePiece(m: Models, name: string) {
  const p = m.pieces.get(name);
  if (!p) throw new Error(`Missing model piece ${name}`);
  const c = p.clone(true);
  c.position.set(0, 0, 0);
  return c;
}

/** The Hole 1 windmill rig: returns the root and its two animated nodes. */
export function windmillRig(m: Models) {
  const root = m.windmill.clone(true);
  const body = root.getObjectByName('Body')!;
  const sails = root.getObjectByName('Sails')!;
  const sweepers = root.getObjectByName('Sweepers')!;
  body.rotation.y = -0.45; // face front-left so the tower shows beside the sails
  root.getObjectByName('Edge')?.traverse((o) => { o.castShadow = false; }); // flush with the turf
  return {
    root,
    update(angle: number) {
      sweepers.rotation.y = -angle;
      sails.rotation.z = angle * 1.5;
    },
  };
}

/**
 * Collects piece placements and builds one InstancedMesh per piece primitive,
 * so a whole course of walls costs a handful of draw calls.
 */
export class PieceBatch {
  private placements = new Map<string, THREE.Matrix4[]>();
  constructor(private models: Models) {}

  add(name: string, matrix: THREE.Matrix4) {
    if (!this.placements.has(name)) this.placements.set(name, []);
    this.placements.get(name)!.push(matrix.clone());
  }

  /**
   * Lay a wall along the capsule from a to b (table-plane points as 3D vectors, y = 0).
   * The body is tiled with sections stretched to fit exactly; rounded ends cap both sides.
   */
  wall(a: THREE.Vector3, b: THREE.Vector3, kind: 'Stone' | 'Brick', lift = 0) {
    const len = a.distanceTo(b);
    const n = Math.max(1, Math.round(len / KIT.section));
    const stretch = len / (n * KIT.section);
    const yaw = -Math.atan2(b.z - a.z, b.x - a.x);
    const base = new THREE.Matrix4().makeTranslation(a.x, 0, a.z).multiply(new THREE.Matrix4().makeRotationY(yaw));
    const capY = KIT.bodyH + lift;
    for (let i = 0; i < n; i++) {
      const at = new THREE.Matrix4().makeTranslation(i * KIT.section * stretch, 0, 0).multiply(new THREE.Matrix4().makeScale(stretch, 1, 1));
      this.add(`${kind}Section`, base.clone().multiply(at));
      const cap = new THREE.Matrix4().makeTranslation(i * KIT.section * stretch, capY, 0).multiply(new THREE.Matrix4().makeScale(stretch, 1, 1));
      this.add('CapSection', base.clone().multiply(cap));
    }
    const endB = new THREE.Matrix4().makeTranslation(len, 0, 0);
    const endA = new THREE.Matrix4().makeRotationY(Math.PI);
    this.add(`${kind}End`, base.clone().multiply(endB));
    this.add(`${kind}End`, base.clone().multiply(endA));
    this.add('CapEnd', base.clone().multiply(new THREE.Matrix4().makeTranslation(len, capY, 0)));
    this.add('CapEnd', base.clone().multiply(new THREE.Matrix4().makeTranslation(0, capY, 0)).multiply(new THREE.Matrix4().makeRotationY(Math.PI)));
  }

  build(): THREE.Group {
    const group = new THREE.Group();
    for (const [name, mats] of this.placements) {
      const piece = this.models.pieces.get(name);
      if (!piece) continue;
      piece.updateMatrixWorld(true);
      const inv = new THREE.Matrix4().copy(piece.matrixWorld).invert();
      piece.traverse((o) => {
        if (!(o instanceof THREE.Mesh)) return;
        const local = inv.clone().multiply(o.matrixWorld);
        const im = new THREE.InstancedMesh(o.geometry, o.material, mats.length);
        mats.forEach((m, i) => im.setMatrixAt(i, m.clone().multiply(local)));
        im.castShadow = o.castShadow;
        im.receiveShadow = true;
        im.computeBoundingSphere();
        group.add(im);
      });
    }
    return group;
  }
}
